void out_fifo_reset( Out_Fifo out_fifo , Boolean reset )
{
    Fifo_Node *node ; 
    
    do
    {
        node = fifo_remove( out_fifo->q_p ); 
        
        if( node )
        {            
            fifo_insert( out_fifo->q_f , node ); 
        }
    }
    while( node );
    
    out_exec_stop( out_fifo->out , reset ) ; 
}

